use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let str_input = input.as_str().unwrap();
    let parts: Vec<&str> = str_input.split('.').collect();
    let mut valid_parts = Vec::new();
    for part in parts {
        if part.is_empty() {
            continue;
        }
        let num = part.parse::<i64>().unwrap();
        if num == 0 {
            continue;
        }
        if num < 0 || num > 255 {
            continue;
        }
        valid_parts.push(num);
    }
    if valid_parts.len() != 4 {
        return Value::Bool(false);
    }
    Value::Bool(true)
}
